import XCTest
@testable import Minutes

final class MergeTests: XCTestCase {
    func testAssignsSpeakersSmoothsIslandsAndOrdersByFirstAppearance() {
        func w(_ t: String, _ s: Double) -> Word { Word(text: t, start: s, end: s + 0.4) }
        let words = [w("Hi", 0), w("there.", 0.5), w("Hello!", 2.0), w("How", 2.5), w("are", 3.0),
                     w("uh", 3.5), w("you?", 4.0), w("Great.", 6.1)]
        let segments = [
            Merge.Segment(speaker: "S7", start: 0, end: 1.0),   // first voice → Speaker 1
            Merge.Segment(speaker: "S3", start: 1.9, end: 3.4),
            Merge.Segment(speaker: "S7", start: 3.4, end: 3.95), // 1-word island inside S3 → absorbed
            Merge.Segment(speaker: "S3", start: 4.0, end: 4.5),
            Merge.Segment(speaker: "S7", start: 6.5, end: 7.0),  // "Great." has no overlap → nearest
        ]
        let turns = Merge.turns(words: words, segments: segments)
        XCTAssertEqual(turns.map(\.speaker), [0, 1, 0])
        XCTAssertEqual(turns.map(\.text), ["Hi there.", "Hello! How are uh you?", "Great."])
        XCTAssertEqual(turns[1].start, 2.0)
        XCTAssertTrue(Merge.turns(words: [], segments: segments).isEmpty)
    }
}

import Foundation
import LLM

/// Qwen3-1.7B (Q4_K_M GGUF, Apache-2.0) via llama.cpp/Metal. Granola-style: enhances the user's own notes with the transcript.
enum NotesWriter {
    static let remoteURL = URL(string: "https://huggingface.co/unsloth/Qwen3-1.7B-GGUF/resolve/main/Qwen3-1.7B-Q4_K_M.gguf")!
    static let modelFile = URL.applicationSupportDirectory.appending(path: "Models/Qwen3-1.7B-Q4_K_M.gguf")

    static let system = """
    You are an expert meeting note-taker. Using ONLY facts from the transcript (and the user's own notes, \
    which show what they care about), reply in Markdown with exactly this structure and nothing else:
    # <title, max 6 words>
    ## Summary
    <3-5 sentence summary>
    ## Key Decisions
    - <one decision per line, or "- None">
    ## Action Items
    - [<owner: a speaker name, or Unassigned>] <task>
    Be concise and specific. Never invent names, numbers or dates.
    """

    struct Output { var title: String?; var notes: Notes }

    static func write(_ m: Meeting, onText: @escaping @MainActor (String) -> Void) async throws -> Output {
        // Model load is synchronous and ~1 s; keep it off the main thread. Weights are mmapped, freed when `bot` goes away.
        let bot = await Task.detached {
            LLM(from: modelFile, topK: 20, topP: 0.8, temp: 0.4, repeatPenalty: 1.05, maxTokenCount: 8192)
        }.value
        guard let bot else { throw CocoaError(.fileReadCorruptFile) }
        bot.systemPrompt = system

        let streamed = StreamBuffer()
        bot.update = { [weak bot] delta in // weak: a strong capture would leak the model + KV cache (~2 GB)
            guard let delta else { return }
            let text = streamed.append(delta)
            if text.count > 6000 { bot?.stop() } // runaway guard; real notes are < 3000 chars
            Task { @MainActor in onText(text) }
        }

        var prompt = ""
        if !m.userNotes.isEmpty { prompt += "My notes:\n\(m.userNotes)\n\n" }
        prompt += "Transcript:\n\(fit(m.transcriptText))\n\nWrite the meeting notes. /no_think"
        await bot.respond(to: prompt, thinking: .suppressed)
        return parse(bot.output)
    }

    /// ponytail: char-based budget (~4 chars/token) keeps prompt ≈ 6k tokens inside the 8k context;
    /// keeps the start and end of very long (>40 min) meetings. Map-reduce over chunks if that ever matters.
    static func fit(_ transcript: String, limit: Int = 24_000) -> String {
        guard transcript.count > limit else { return transcript }
        return transcript.prefix(limit * 2 / 3) + "\n[…]\n" + transcript.suffix(limit / 3)
    }

    static func parse(_ raw: String) -> Output {
        let text = raw.replacingOccurrences(of: "<think>[\\s\\S]*?</think>", with: "", options: .regularExpression)
        var out = Output(title: nil, notes: Notes())
        var section = ""
        var summary: [String] = []
        for line in text.components(separatedBy: .newlines) {
            let l = line.trimmingCharacters(in: .whitespaces)
            if l.hasPrefix("#") || (l.hasPrefix("**") && l.hasSuffix("**")) {
                let heading = l.trimmingCharacters(in: CharacterSet(charactersIn: "#*: ")).lowercased()
                if heading.contains("summary") { section = "summary" }
                else if heading.contains("decision") { section = "decisions" }
                else if heading.contains("action") { section = "actions" }
                else if out.title == nil, l.hasPrefix("# ") { out.title = l.trimmingCharacters(in: CharacterSet(charactersIn: "# ")) }
                continue
            }
            let item = l.replacingOccurrences(of: "^([-*•]|\\d+[.)])\\s+", with: "", options: .regularExpression)
            if item.isEmpty || ["none", "none.", "n/a"].contains(item.lowercased()) { continue }
            switch section {
            case "summary": summary.append(item)
            case "decisions": out.notes.decisions.append(item)
            case "actions":
                if let match = item.firstMatch(of: #/^\[(.*?)\]\s*(.+)$/#) {
                    let owner = match.1.trimmingCharacters(in: .whitespaces)
                    let unassigned = owner.isEmpty || ["x", "unassigned"].contains(owner.lowercased())
                    out.notes.actions.append(ActionItem(text: String(match.2), owner: unassigned ? nil : owner))
                } else {
                    out.notes.actions.append(ActionItem(text: item))
                }
            default: break
            }
        }
        out.notes.summary = summary.joined(separator: " ")
        // Never lose output: if the model ignored the format, keep its text as the summary.
        if out.notes.summary.isEmpty && out.notes.decisions.isEmpty && out.notes.actions.isEmpty {
            out.notes.summary = text.trimmingCharacters(in: .whitespacesAndNewlines)
        }
        return out
    }
}

/// Accumulates streamed deltas from llama.cpp's generation thread.
private final class StreamBuffer: @unchecked Sendable {
    private let lock = NSLock()
    private var text = ""
    func append(_ delta: String) -> String { lock.withLock { text += delta; return text } }
}

import SwiftUI

struct HomeView: View {
    @Environment(Store.self) private var store
    @State private var path: [UUID] = []
    @State private var recording = false
    @State private var importing = false
    @State private var importError: String?

    var body: some View {
        NavigationStack(path: $path) {
            Group {
                if store.meetings.isEmpty {
                    empty
                } else {
                    List {
                        ForEach(store.meetings) { m in
                            NavigationLink(value: m.id) { MeetingRow(meeting: m) }
                                .listRowBackground(Color.canvas)
                                .listRowSeparatorTint(Color.hairline)
                        }
                        .onDelete { $0.map { store.meetings[$0].id }.forEach(store.delete) }
                    }
                    .listStyle(.plain)
                    .scrollContentBackground(.hidden)
                }
            }
            .background(Color.canvas.ignoresSafeArea())
            .navigationTitle("Minutes")
            .navigationDestination(for: UUID.self) { MeetingView(id: $0) }
            .safeAreaInset(edge: .bottom) { actions }
        }
        .fullScreenCover(isPresented: $recording) {
            RecordView { id in path = [id] }
        }
        .fileImporter(isPresented: $importing, allowedContentTypes: [.audio]) { result in
            do { path = [try store.importAudio(from: result.get())] } catch { importError = error.localizedDescription }
        }
        #if DEBUG
        // CLI test hook: `-autoImport <path>` imports a file and opens it, as the Import button would.
        .task {
            if UserDefaults.standard.double(forKey: "autoRecord") > 0 { recording = true } // `-autoRecord <seconds>`
            if let p = UserDefaults.standard.string(forKey: "autoImport") {
                do { path = [try store.importAudio(from: URL(filePath: p))] } catch { importError = error.localizedDescription }
            }
        }
        #endif
        .alert("Couldn't import audio", isPresented: .constant(importError != nil)) {
            Button("OK") { importError = nil }
        } message: { Text(importError ?? "") }
    }

    private var empty: some View {
        VStack(spacing: 12) {
            Spacer()
            Image(systemName: "text.bubble").font(.system(size: 36)).foregroundStyle(Color.inkSecondary)
            Text("No meetings yet").font(.title3.weight(.semibold)).foregroundStyle(Color.ink)
            Text("Record a conversation or import audio. Transcripts, speakers and notes are made on this iPhone.")
                .font(.subheadline).foregroundStyle(Color.inkSecondary).multilineTextAlignment(.center)
            Spacer()
        }
        .padding(.horizontal, 40)
        .frame(maxWidth: .infinity)
    }

    private var actions: some View {
        HStack(spacing: 12) {
            Button { importing = true } label: {
                Image(systemName: "square.and.arrow.down")
                    .font(.title3.weight(.medium))
                    .frame(width: 56, height: 56)
                    .background(Color.surface, in: .circle)
                    .overlay(Circle().stroke(Color.hairline))
            }
            .buttonStyle(PressStyle())
            .accessibilityLabel("Import audio")

            PrimaryButton(title: "Record", systemImage: "mic.fill", tint: .record) { recording = true }
        }
        .padding(.horizontal, 16)
        .padding(.top, 12)
        .background(.regularMaterial)
    }
}

private struct MeetingRow: View {
    let meeting: Meeting

    var body: some View {
        VStack(alignment: .leading, spacing: 4) {
            Text(meeting.title).font(.headline).foregroundStyle(Color.ink).lineLimit(1)
            Text("\(meeting.date.formatted(date: .abbreviated, time: .shortened)) · \(meeting.duration.clock)")
                .font(.subheadline.monospacedDigit()).foregroundStyle(Color.inkSecondary)
            switch meeting.stage {
            case .done:
                if let summary = meeting.notes?.summary {
                    Text(summary).font(.subheadline).foregroundStyle(Color.inkSecondary).lineLimit(2)
                }
            case .failed:
                Label("Needs attention", systemImage: "exclamationmark.circle").font(.footnote).foregroundStyle(Color.record)
            default:
                HStack(spacing: 6) {
                    PulsingDot()
                    Text(meeting.stage.rawValue + "…").font(.footnote).foregroundStyle(Color.accent)
                }
            }
        }
        .padding(.vertical, 6)
    }
}

/// Soft "working" indicator — used instead of a bare spinner.
struct PulsingDot: View {
    var color: Color = .accent
    @State private var on = false
    @Environment(\.accessibilityReduceMotion) private var reduceMotion

    var body: some View {
        Circle().fill(color).frame(width: 8, height: 8)
            .opacity(on ? 0.3 : 1)
            .onAppear {
                guard !reduceMotion else { return }
                withAnimation(.easeInOut(duration: 0.8).repeatForever()) { on = true }
            }
    }
}

