import FluidAudio
import Foundation

/// LS-EEND (end-to-end neural diarization, CALLHOME variant, ~43 MB CoreML via FluidAudio).
/// Chosen over pyannote+VBx after device testing: VBx merged two similar real voices into one speaker,
/// while LS-EEND separated them and stayed consistent across a 10-minute file (99/99 turns).
enum Diarizer {
    static func prepare(progress: @escaping @Sendable (Double) -> Void) async throws {
        _ = try await LSEENDModel.loadFromHuggingFace(variant: .callhome, progressHandler: { progress($0.fractionCompleted) })
        progress(1)
    }

    static func segments(for url: URL) async throws -> [Merge.Segment] {
        let diarizer = try LSEENDDiarizer(model: try await LSEENDModel.loadFromHuggingFace(variant: .callhome))
        let segments = try diarizer.processComplete(audioFileURL: url).speakers.values.flatMap(\.finalizedSegments)
        // Drop phantom speakers with under a second of speech in total (noise blips).
        var total: [Int: Float] = [:]
        for s in segments { total[s.speakerIndex, default: 0] += s.duration }
        return segments.filter { total[$0.speakerIndex, default: 0] >= 1 }.map {
            Merge.Segment(speaker: String($0.speakerIndex), start: Double($0.startTime), end: Double($0.endTime))
        }
    }
}

