import FluidAudio
import Foundation

/// pyannote community-1 (segmentation + WeSpeaker + PLDA + VBx) via FluidAudio CoreML; ~22 MB, runs on the ANE.
enum Diarizer {
    static func prepare(progress: @escaping @Sendable (Double) -> Void) async throws {
        _ = try await OfflineDiarizerModels.load(progressHandler: { progress($0.fractionCompleted) })
        progress(1)
    }

    static func segments(for url: URL) async throws -> [Merge.Segment] {
        var config = OfflineDiarizerConfig.default
        // ponytail: capped at 2 speakers per the brief; make it a per-meeting setting when 3+ person meetings matter.
        config.clustering.maxSpeakers = 2
        let manager = OfflineDiarizerManager(config: config)
        manager.initialize(models: try await OfflineDiarizerModels.load())
        let result = try await manager.process(url)
        return result.segments.map {
            Merge.Segment(speaker: $0.speakerId, start: Double($0.startTimeSeconds), end: Double($0.endTimeSeconds))
        }
    }
}

