import FluidAudio
import Foundation

/// NVIDIA Sortformer v2.1, high-context config (end-to-end neural diarization, ~252 MB CoreML via FluidAudio).
/// Chosen by testing every FluidAudio diarizer on real recordings: pyannote+VBx merged two similar in-person
/// voices, LS-EEND merged podcast audio played through a speaker; only Sortformer separated every case and
/// kept identities consistent across a 10-minute file (97/99 turns, the other 2 undetected rather than swapped).
enum Diarizer {
    static let config = SortformerConfig.highContextV2_1

    static func prepare(progress: @escaping @Sendable (Double) -> Void) async throws {
        _ = try await SortformerModels.loadFromHuggingFace(config: config, progressHandler: { progress($0.fractionCompleted) })
        progress(1)
    }

    static func segments(for url: URL) async throws -> [Merge.Segment] {
        let diarizer = SortformerDiarizer(config: config)
        diarizer.initialize(models: try await SortformerModels.loadFromHuggingFace(config: config))
        let segments = try diarizer.processComplete(audioFileURL: url).speakers.values.flatMap(\.finalizedSegments)
        // Drop phantom speakers: Sortformer occasionally flickers a third label for a few seconds (≈5 % of speech);
        // real participants in tests always held ≥ 16 %. Their words fall back to the nearest real speaker in Merge.
        var share: [Int: Float] = [:]
        for s in segments { share[s.speakerIndex, default: 0] += s.duration }
        let total = share.values.reduce(0, +)
        return segments.filter { share[$0.speakerIndex, default: 0] >= 0.1 * total }.map {
            Merge.Segment(speaker: String($0.speakerIndex), start: Double($0.startTime), end: Double($0.endTime))
        }
    }
}

