func apple(_ url: URL, _ id: String) async throws -> String {
  let locale = Locale(identifier: id)
  guard let supported = await SpeechTranscriber.supportedLocale(equivalentTo: locale) else { return "(\(id) unsupported)" }
  let module = SpeechTranscriber(locale: supported, transcriptionOptions: [], reportingOptions: [], attributeOptions: [])
