  if let r = try await AssetInventory.assetInstallationRequest(supporting: [module]) { try await r.downloadAndInstall() }
  let analyzer = SpeechAnalyzer(modules: [module])
  let collect = Task { var s = ""; for try await r in module.results where r.isFinal { s += String(r.text.characters) }; return s }
  let file = try AVAudioFile(forReading: url)
  if let last = try await analyzer.analyzeSequence(from: file) { try await analyzer.finalizeAndFinish(through: last) } else { await analyzer.cancelAndFinishNow() }
  return try await collect.value
}
