     1	import AVFoundation
     2	import Speech
     3	
     4	/// iOS 26 on-device speech-to-text (SpeechAnalyzer) with word timestamps.
     5	/// One instance per recording or imported file. Not Apple Intelligence: the model is an OS-managed asset.
     6	@MainActor @Observable
     7	final class Transcriber {
     8	    private(set) var finalText = ""
     9	    private(set) var volatileText = ""
    10	    private(set) var words: [Word] = []
    11	
    12	    let format: AVAudioFormat
    13	    private let module: SpeechTranscriber
    14	    private let analyzer: SpeechAnalyzer
    15	    private let input: AsyncStream<AnalyzerInput>.Continuation
    16	    private var results: Task<Void, Error>?
    17	
    18	    nonisolated static let locale = Locale(identifier: "en-US")
    19	
    20	    /// False in the Simulator and on unsupported iPhones; the app then falls back to `Parakeet`.
    21	    nonisolated static var isAvailable: Bool { SpeechTranscriber.isAvailable }
    22	
    23	    nonisolated static func makeModule() -> SpeechTranscriber {
    24	        SpeechTranscriber(locale: locale, transcriptionOptions: [],
    25	                          reportingOptions: [.volatileResults], attributeOptions: [.audioTimeRange])
    26	    }
    27	
    28	    /// Reserves the locale for this app (required before use) and installs the English model once.
    29	    nonisolated static func installAssets(progress: @escaping @Sendable (Double) -> Void) async throws {
    30	        let reserved = await AssetInventory.reservedLocales
    31	        if !reserved.contains(where: { $0.identifier(.bcp47) == locale.identifier(.bcp47) }) {
    32	            try await AssetInventory.reserve(locale: locale)
    33	        }
    34	        if let request = try await AssetInventory.assetInstallationRequest(supporting: [makeModule()]) {
    35	            let observation = request.progress.observe(\.fractionCompleted) { p, _ in progress(p.fractionCompleted) }
    36	            try await request.downloadAndInstall()
    37	            observation.invalidate()
    38	        }
    39	        progress(1)
    40	    }
    41	
    42	    init() async throws {
    43	        module = Self.makeModule()
    44	        analyzer = SpeechAnalyzer(modules: [module])
    45	        guard let format = await SpeechAnalyzer.bestAvailableAudioFormat(compatibleWith: [module]) else {
    46	            throw CocoaError(.featureUnsupported)
    47	        }
    48	        self.format = format
    49	        let (stream, continuation) = AsyncStream<AnalyzerInput>.makeStream()
    50	        input = continuation
    51	        results = Task { [module] in
    52	            for try await result in module.results { self.handle(result) }
    53	        }
    54	        try await analyzer.start(inputSequence: stream)
    55	    }
    56	
    57	    /// Apple stretches the first word after a pause back over the silence ("Great." 36.78–38.04 s, spoken at
    58	    /// ~37.8 s), which would hand it to the previous speaker; keep only its last 0.6 s. (Parakeet stretches the
    59	    /// other way — the last word before a pause — which plain overlap in `Merge` already handles.)
    60	    nonisolated static func trimmed(_ w: Word) -> Word {
    61	        Word(text: w.text, start: max(w.start, w.end - 0.6), end: w.end)
    62	    }
